examples.sdk:
import { configure, checkPNRStatus } from "railkit";

configure(process.env.RAILKIT_API_KEY);
const result = await checkPNRStatus("1234567890");
console.log(result.data.passengers);

examples.javascript:
const response = await fetch(
  "https://api.railkit.in/api/checkPNRStatus/1234567890",
  { headers: { "x-api-key": process.env.RAILKIT_API_KEY } }
);
const result = await response.json();

